// Golden tests for the moe mascot port: every frame in
// fixtures/mascots/moe.frames.txt / moe.markup.txt (generated by gen.sh moe
// from Atrium's moe_mascot.py) must match exactly. Run: node --test web/test/*.test.mjs
import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as moe from '../dist/assets/js/mascots/moe.js';
import { COMBOS, displayWidth, frameSpans } from '../dist/assets/js/mascots/common.js';
import { setWordClock } from '../dist/assets/js/mascots/mood.js';
import { goldenTests } from './fixtures/mascots/golden.mjs';

goldenTests('moe', moe);

test('moe: meta follows the theme API', () => {
  assert.equal(moe.meta.id, 'moe');
  assert.equal(moe.meta.panel, '#2b1d2e');
  assert.equal(moe.meta.moods, true);
  for (const fn of ['lines', 'spans', 'render', 'bubble', 'say']) assert.equal(typeof moe[fn], 'function', fn);
});

test('moe: every state x tool, exact size, spans say the same text', () => {
  for (const [cols, rows] of [[48, 14], [61, 17], [100, 24], [160, 24]]) {
    for (const [state, tool] of COMBOS) {
      for (const tick of [0, 7, 89, 431]) {
        const ls = moe.lines(state, tick, tool, null, null, cols, rows);
        assert.equal(ls.length, rows);
        for (const l of ls) assert.equal(displayWidth(l), cols);
        const sp = moe.spans(state, tick, tool, null, null, cols, rows);
        assert.deepEqual(sp.map((r) => r.map((run) => run[0]).join('')), ls);
        for (const row of sp) {
          for (let i = 1; i < row.length; i++) {
            assert.notEqual(row[i][1], row[i - 1][1], 'neighbouring runs share a colour');
          }
        }
      }
    }
  }
});

test('moe: a frame is a pure function of its inputs', () => {
  const a = moe.lines('idle', 1234, null, 'happy', ['night', 'music'], 80, 20);
  moe.lines('tool', 5, 'Bash', null, null, 160, 24);
  const b = moe.lines('idle', 1234, null, 'happy', new Set(['music', 'night']), 80, 20);
  assert.deepEqual(a, b);
  assert.deepEqual(moe.lines('idle', 3, null, null, 'night,music', 80, 20),
    moe.lines('idle', 3, null, null, ['night', 'music'], 80, 20));
});

test('moe: bubbles per state, tool, MCP tool and mood', () => {
  assert.equal(moe.bubble('tool', 'mcp__srv__lookup'), 'まほう発動！ lookup ✧');
  assert.equal(moe.bubble('tool', null), 'まほう発動！ magic ✧');
  assert.equal(moe.bubble('idle', null, 'sleepy'), 'ねむい… sleepy (´-ω-)zz');
  assert.equal(moe.bubble('thinking', null, 'sleepy'), 'うーん… let me think (｡•ˇ‸ˇ•｡)');
  assert.equal(moe.bubble('nonsense'), moe.bubble('idle'));
});

test('moe: say words topics, rotating variants', () => {
  let now = 1000;
  setWordClock(() => now);
  assert.equal(moe.say(['model', 'qwen3']), 'あたらしい子？ hello, qwen3 ✧');
  assert.equal(moe.say(['event', 'Standup', 10]), 'あと10分！ Standup in 10 min');
  const first = moe.say(['poke']);
  assert.equal(moe.say(['poke']), first, 'the same variant while it is being said');
  now += 10;
  assert.notEqual(moe.say(['poke']), first, 'the next one when it comes round again');
  assert.equal(moe.say(['nope']), 'nope');
});

test('moe: emote over the head, steady under reduce motion', () => {
  const base = { state: 'idle', tick: 30, cols: 80, rows: 20, mood: 'happy', scene: ['night'] };
  const { head } = moe.render('idle', 30, null, 'happy', ['night'], 80, 20);
  const text = (sp) => sp.map((r) => r.map((run) => run[0]).join(''));
  const steady = text(frameSpans(moe, { ...base, tick: 90, calm: true, emote: ['<3', 'love', 0.1] }));
  assert.equal(steady[head[1]].slice(head[0], head[0] + 2), '<3');
  const popping = text(frameSpans(moe, { ...base, emote: ['<3', 'love', 0.1] }));
  assert.equal(popping[head[1]][head[0]], '.');
  const floated = frameSpans(moe, { ...base, emote: ['!', 'warn', 2.0] });
  const run = floated[head[1] - 1].find((r) => r[0].includes('!'));
  assert.equal(run[1], moe.emoteColours.warn);
});
